package dev.thefoolish.generated.anishelf;
import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.util.*;
public final class MainActivity extends AppScreen{private LinearLayout results;private EditText query;private Button search;private ProgressBar progress;protected void render(){title("Browse");subtitle("Browse installed sources and search their catalogs. Built-in providers are ready immediately; additional repositories remain optional and user-controlled.");query=new EditText(this);query.setHint("Search anime");query.setSingleLine(true);query.setTextColor(TEXT);query.setHintTextColor(MUTED);query.setTextSize(16);query.setPadding(dp(14),0,dp(14),0);query.setBackground(round(SURFACE,14));body.addView(query,new LinearLayout.LayoutParams(-1,dp(52)));search=button("Search installed sources");search.setOnClickListener(v->searchAsync());body.addView(search);LinearLayout source=card("Installed source",BuiltInProviderCatalog.provenance());source.setOnClickListener(v->AppNavigator.open(this,ProvidersActivity.class));body.addView(source);progress=new ProgressBar(this);progress.setVisibility(View.GONE);LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,dp(42));pp.setMargins(0,dp(4),0,dp(4));body.addView(progress,pp);section("Search results");results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);body.addView(results);showReady();}private void showReady(){results.removeAllViews();TextView t=text("Enter a title to search the providers already installed in this app.",14,false);t.setTextColor(MUTED);results.addView(t);}private void searchAsync(){String q=query.getText().toString().trim();if(q.length()==0){query.setError("Enter a title");return;}search.setEnabled(false);progress.setVisibility(View.VISIBLE);results.removeAllViews();results.addView(text("Searching installed sources…",14,false));new Thread(()->{List<AnimeItem> found=new ArrayList<>();List<String> failures=new ArrayList<>();List<MediaProvider> providers=new ArrayList<>(BuiltInProviderCatalog.providers());for(ExtensionRecord x:new ExtensionManager(this).known())if(x.state==ExtensionRecord.State.ENABLED)providers.add(new RepositoryMediaProvider(x));for(MediaProvider p:providers){try{found.addAll(p.search(q));}catch(Exception e){String m=e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();failures.add(p.displayName()+": "+m);}}runOnUiThread(()->showSearchResult(q,found,failures));}).start();}private void showSearchResult(String q,List<AnimeItem> found,List<String> failures){search.setEnabled(true);progress.setVisibility(View.GONE);results.removeAllViews();if(!failures.isEmpty()){LinearLayout c=card("Some sources could not be reached",android.text.TextUtils.join("\n",failures));results.addView(c);}if(found.isEmpty()){String msg=failures.isEmpty()?"No matches found for \""+q+"\". Try another title.":"No results were returned because one or more sources failed. Check the error above and your connection.";TextView empty=text(msg,14,false);empty.setTextColor(MUTED);results.addView(empty);return;}for(AnimeItem a:found){String meta=(a.episodes>0?a.episodes+" episodes · ":"")+a.provider;LinearLayout c=card(a.title,meta);c.setClickable(true);c.setOnClickListener(v->{Intent i=new Intent(this,DetailActivity.class);i.putExtra("id",a.id);i.putExtra("title",a.title);i.putExtra("summary",a.summary);i.putExtra("provider",a.provider);i.putExtra("episodes",a.episodes);startActivity(i);});results.addView(c);}}}
